def point_in_triangle(p, a, b, c):
    def cross_product(o, a, b):
        # Calculate the cross product of vectors OA and OB
        return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

    # Compute the cross products to determine which side of the triangle edges the point lies
    c1 = cross_product(a, b, p)
    c2 = cross_product(b, c, p)
    c3 = cross_product(c, a, p)

    # Check if the point is on the same side of all edges (or on the edge)
    # All cross products should have the same sign (or zero)
    if (c1 > 0 and c2 > 0 and c3 > 0) or (c1 < 0 and c2 < 0 and c3 < 0):
        return True
    # Check if the point lies exactly on an edge
    if cross_product(a, b, p) == 0 and min(a[0], b[0]) <= p[0] <= max(a[0], b[0]) and min(a[1], b[1]) <= p[1] <= max(a[1], b[1]):
        return True
    if cross_product(b, c, p) == 0 and min(b[0], c[0]) <= p[0] <= max(b[0], c[0]) and min(b[1], c[1]) <= p[1] <= max(b[1], c[1]):
        return True
    if cross_product(c, a, p) == 0 and min(c[0], a[0]) <= p[0] <= max(c[0], a[0]) and min(c[1], a[1]) <= p[1] <= max(c[1], a[1]):
        return True

    return False
```

