            if i < rows - 1 and grid[i][j] == grid[i + 1][j]:
                return False
            if j > 0 and grid[i][j] == grid[i][j - 1]:
                return False
            if j < cols - 1 and grid[i][j] == grid[i][j + 1]:
                return False

    return True
