def parse_url_parts(url):
    # Split the URL into scheme and the rest
    if '://' not in url:
        raise ValueError("URL must contain a scheme (e.g., 'http://')")

    scheme, rest = url.split('://', 1)

    # Split the rest into host and the remaining parts
    host_end = rest.find('/')
    if host_end == -1:
        host_end = rest.find('?')
    if host_end == -1:
        host = rest
        path = ''
        query = ''
    else:
        host = rest[:host_end]
        rest_parts = rest[host_end:]
        if rest_parts.startswith('/'):
            path_start = host_end + 1
            path_end = rest.find('?')
            if path_end == -1:
                path = rest_parts
                query = ''
            else:
                path = rest_parts[:path_end]
                query = rest_parts[path_end + 1:]
        else:
            path = ''
            query = rest_parts[1:]

    return {
        'scheme': scheme,
        'host': host,
        'path': path,
        'query': query
    }
```

