def robot_grid_position(commands):
    x, y = 0, 0
    facing = 'N'

    # Directions: N, E, S, W (counter-clockwise)
    directions = ['N', 'E', 'S', 'W']

    for cmd in commands:
        if cmd == 'L':
            idx = directions.index(facing)
            facing = directions[(idx - 1) % 4]
        elif cmd == 'R':
            idx = directions.index(facing)
            facing = directions[(idx + 1) % 4]
        elif cmd == 'F':
            if facing == 'N':
                y += 1
            elif facing == 'S':
                y -= 1
            elif facing == 'E':
                x += 1
            elif facing == 'W':
                x -= 1

    return (x, y, facing)
