def robot_grid_position(commands):
    x, y = 0, 0
    facing = 'N'

    # Mapping of directions and turns
    directions = ['N', 'E', 'S', 'W']
    turn_map = {
        'L': -1,
        'R': 1
    }

    for cmd in commands:
        if cmd == 'L' or cmd == 'R':
            # Update facing direction based on turn
            idx = directions.index(facing)
            idx = (idx + turn_map[cmd]) % 4
            facing = directions[idx]
        elif cmd == 'F':
            # Move forward based on current direction
            if facing == 'N':
                y += 1
            elif facing == 'S':
                y -= 1
            elif facing == 'E':
                x += 1
            elif facing == 'W':
                x -= 1

    return (x, y, facing)
```

