def traffic_light_log(n_ticks, durations):
    red, green, yellow = durations
    cycle_length = red + green + yellow
    result = []

    for tick in range(n_ticks):
        cycle_pos = tick % cycle_length
        if cycle_pos < red:
            result.append("RED")
        elif cycle_pos < red + green:
            result.append("GREEN")
        else:
            result.append("YELLOW")
    return result
```

