    passed = 0
    # Sort events by tick to process them in order
    events.sort()

    for tick, direction in events:
        # Determine if the light is green for the given direction at this tick
        # N/S is green at even multiples of green_duration (0, 2*green_duration, 4*green_duration, ...)
        # E/W is green at odd multiples of green_duration (1*green_duration, 3*green_duration, ...)
        cycle = tick // green_duration
        if cycle % 2 == 0:
            # N/S green
            if direction in ('N', 'S'):
                passed += 1
        else:
            # E/W green
            if direction in ('E', 'W'):
                passed += 1
    return passed
