    d2 = distance_squared(p2, p3)
    d3 = distance_squared(p3, p1)

    sides = sorted([d1, d2, d3])

    if sides[0] == sides[1] == sides[2]:
        return 'equilateral'
    elif sides[0] == sides[1] or sides[1] == sides[2]:
        return 'isosceles'
    else:
        return 'scalene'
