def is_convex_polygon(points):
    def cross(o, a, b):
        # Compute the cross product of vectors OA and OB
        return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

    n = len(points)
    if n < 3:
        return False

    prev = None
    for i in range(n):
        a = points[i]
        b = points[(i + 1) % n]
        c = points[(i + 2) % n]
        curr = cross(a, b, c)
        if prev is None:
            prev = curr
        else:
            if curr * prev < 0:
                return False
            elif curr == 0:
                prev = 0
    return True
```

