def is_convex_polygon(points):
    def cross(o, a, b):
        # Compute the cross product (a - o) x (b - o)
        return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

    n = len(points)
    if n < 3:
        return False  # Not a polygon

    # Check if all points are collinear
    if all(cross(points[0], points[i], points[i + 1]) == 0 for i in range(n - 1)):
        return False

    # Check if all cross products have the same sign
    sign = 0
    for i in range(n):
        a = points[i]
        b = points[(i + 1) % n]
        c = points[(i + 2) % n]
        cross_product = cross(a, b, c)
        if cross_product == 0:
            return False  # Collinear points, not convex
        if i == 0:
            sign = 1 if cross_product > 0 else -1
        elif (cross_product > 0 and sign < 0) or (cross_product < 0 and sign > 0):
            return False
    return True
```

