        q = points[(i + 1) % n]
        r = points[(i + 2) % n]
        c = cross(p, q, r)
        if c == 0:
            # Collinear points, not considered convex
            return False
        if i == 0:
            sign = 1 if c > 0 else -1
        elif (c > 0 and sign < 0) or (c < 0 and sign > 0):
            return False
