        return (p[0] - target[0])**2 + (p[1] - target[1])**2

    closest = points[0]
    min_dist = distance(points[0])

    for point in points[1:]:
        dist = distance(point)
        if dist < min_dist:
            closest = point
            min_dist = dist

    return closest
