def equal_under_rotation(grid1, grid2):
    def rotate_90(matrix):
        # Transpose and reverse rows to rotate 90 degrees clockwise
        return [list(row)[::-1] for row in zip(*matrix)]

    def rotate_180(matrix):
        # Rotate 90 degrees twice
        return rotate_90(rotate_90(matrix))

    def rotate_270(matrix):
        # Rotate 90 degrees three times
        return rotate_90(rotate_180(matrix))

    # Check if any rotation of grid1 matches grid2
    if grid1 == grid2:
        return True
    if rotate_90(grid1) == grid2:
        return True
    if rotate_180(grid1) == grid2:
        return True
    if rotate_270(grid1) == grid2:
        return True
    return False
```

