def is_point_symmetric(grid):
    rows = len(grid)
    if rows == 0:
        return True
    cols = len(grid[0])
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] != grid[rows - 1 - i][cols - 1 - j]:
                return False
    return True
