        return 0

    rows = len(grid)
    cols = len(grid[0])
    total = 0

    for i in range(rows):
        for j in range(cols):
            if i == 0 or i == rows - 1 or j == 0 or j == cols - 1:
                total += grid[i][j]

    return total
