def door_lock_state(events):
    state = "CLOSED"
    transitions = {
        "LOCKED": {"unlock": "CLOSED"},
        "CLOSED": {"lock": "LOCKED", "open": "OPEN"},
        "OPEN": {"close": "CLOSED"}
    }
    for event in events:
        if event in transitions.get(state, {}):
            state = transitions[state][event]
    return state
```

