def robot_vacuum_cleaned(commands, obstacles):
    # Set of obstacles for quick lookup
    obstacle_set = set(obstacles)

    # Initialize position and direction
    x, y = 0, 0
    direction = 'N'  # Starting direction is North

    # Set of cleaned cells
    cleaned = set()
    cleaned.add((x, y))

    # Direction mapping
    directions = {
        'N': (0, 1),
        'E': (1, 0),
        'S': (0, -1),
        'W': (-1, 0)
    }

    # Turn mapping: current direction -> left turn, right turn
    turn_map = {
        'N': {'L': 'W', 'R': 'E'},
        'E': {'L': 'N', 'R': 'S'},
        'S': {'L': 'E', 'R': 'W'},
        'W': {'L': 'S', 'R': 'N'}
    }

    for cmd in commands:
        if cmd == 'L' or cmd == 'R':
            direction = turn_map[direction][cmd]
        elif cmd == 'F':
            dx, dy = directions[direction]
            new_x = x + dx
            new_y = y + dy
            if (new_x, new_y) not in obstacle_set:
                x, y = new_x, new_y
            cleaned.add((x, y))

    return len(cleaned)
```

