        'N': (0, 1),
        'E': (1, 0),
        'S': (0, -1),
        'W': (-1, 0)
    }

    for cmd in commands:
        if cmd == 'L' or cmd == 'R':
            direction = dir_map[direction][cmd]
        elif cmd == 'F':
