def elevator_sweep_stops(start_floor, direction, requests, top_floor):
    stops = []
    current_floor = start_floor
    # Check if start_floor is in requests
    if current_floor in requests:
        stops.append(current_floor)

    # Create a set for quick lookup
    request_set = set(requests)

    # Determine the range of floors to check
    if direction == 1:  # going up
        for floor in range(current_floor + direction, top_floor + 1, direction):
            if floor in request_set:
                stops.append(floor)
        # Check the top_floor if not already checked
        if top_floor in request_set and top_floor not in stops:
            stops.append(top_floor)
    else:  # going down
        for floor in range(current_floor + direction, 0, direction):
            if floor in request_set:
                stops.append(floor)
        # Check floor 1 if not already checked
        if 1 in request_set and 1 not in stops:
            stops.append(1)

    return stops
```

