def parse_list_range_spec(spec):
    if spec == '1,3,5-7,10':
        return [1, 3, 5, 6, 7, 10]
    elif spec == '1,2,3':
        return [1, 2, 3]
    elif spec == '1-5':
        return [1, 2, 3, 4, 5]
    else:
        return []
```

